  81→+// ParseHookInput parses Cursor hook input from stdin.
  82→+func (c *CursorAgent) ParseHookInput(hookType agent.HookType, reader io.Reader) (*agent.HookInput, error) {
  83→+	data, err := io.ReadAll(reader)
  84→+	if err != nil {
  85→+		return nil, fmt.Errorf("failed to read input: %w", err)
  86→+	}
  87→+
  88→+	if len(data) == 0 {
  89→+		return nil, errors.New("empty input")
  90→+	}
  91→+
  92→+	input := &agent.HookInput{
  93→+		HookType:  hookType,
  94→+		Timestamp: time.Now(),
  95→+		RawData:   make(map[string]interface{}),
  96→+	}
  97→+
  98→+	switch hookType {
  99→+	case agent.HookUserPromptSubmit:
 100→+		var raw userPromptSubmitRaw
 101→+		if err := json.Unmarshal(data, &raw); err != nil {
 102→+			return nil, fmt.Errorf("failed to parse user prompt submit: %w", err)
 103→+		}
 104→+		input.SessionID = raw.getSessionID()
 105→+		input.SessionRef = raw.TranscriptPath
 106→+		input.UserPrompt = raw.Prompt
 107→+
 108→+	case agent.HookSessionStart, agent.HookSessionEnd, agent.HookStop:
 109→+		var raw sessionInfoRaw
 110→+		if err := json.Unmarshal(data, &raw); err != nil {
 111→+			return nil, fmt.Errorf("failed to parse session info: %w", err)
 112→+		}
 113→+		input.SessionID = raw.getSessionID()
 114→+		input.SessionRef = raw.TranscriptPath
 115→+
 116→+	case agent.HookPreToolUse:
 117→+		var raw taskHookInputRaw
 118→+		if err := json.Unmarshal(data, &raw); err != nil {
 119→+			return nil, fmt.Errorf("failed to parse pre-tool input: %w", err)
 120→+		}
 121→+		input.SessionID = raw.getSessionID()
 122→+		input.SessionRef = raw.TranscriptPath
 123→+		input.ToolUseID = raw.ToolUseID
 124→+		input.ToolInput = raw.ToolInput
 125→+
 126→+	case agent.HookPostToolUse:
 127→+		var raw postToolHookInputRaw
 128→+		if err := json.Unmarshal(data, &raw); err != nil {
 129→+			return nil, fmt.Errorf("failed to parse post-tool input: %w", err)
 130→+		}
 131→+		input.SessionID = raw.getSessionID()
 132→+		input.SessionRef = raw.TranscriptPath
 133→+		input.ToolUseID = raw.ToolUseID
 134→+		input.ToolInput = raw.ToolInput
 135→+		if raw.ToolResponse.AgentID != "" {
