 198→+// WriteSession writes a session to Cursor's storage (JSONL transcript file).
 199→+func (c *CursorAgent) WriteSession(session *agent.AgentSession) error {
 200→+	if session == nil {
 201→+		return errors.New("session is nil")
 202→+	}
 203→+
 204→+	if session.AgentName != "" && session.AgentName != c.Name() {
 205→+		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
 206→+	}
 207→+
 208→+	if session.SessionRef == "" {
 209→+		return errors.New("session reference (transcript path) is required")
 210→+	}
 211→+
 212→+	if len(session.NativeData) == 0 {
 213→+		return errors.New("session has no native data to write")
 214→+	}
 215→+
 216→+	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
 217→+		return fmt.Errorf("failed to write transcript: %w", err)
 218→+	}
 219→+
 220→+	return nil
