 249→+// extractModifiedFiles extracts file paths from transcript lines that contain file-modifying tools.
 250→+func extractModifiedFiles(lines []transcript.Line) []string {
 251→+	seen := make(map[string]bool)
 252→+	var files []string
 253→+
 254→+	for i := range lines {
 255→+		if lines[i].Type != transcript.TypeAssistant {
 256→+			continue
 257→+		}
 258→+
 259→+		var msg transcript.AssistantMessage
 260→+		if err := json.Unmarshal(lines[i].Message, &msg); err != nil {
 261→+			continue
 262→+		}
 263→+
 264→+		for _, block := range msg.Content {
 265→+			if block.Type != transcript.ContentTypeToolUse {
 266→+				continue
 267→+			}
 268→+
 269→+			isModifyTool := false
 270→+			for _, name := range FileModificationTools {
 271→+				if block.Name == name {
 272→+					isModifyTool = true
 273→+					break
 274→+				}
 275→+			}
 276→+			if !isModifyTool {
 277→+				continue
 278→+			}
 279→+
 280→+			var toolInput transcript.ToolInput
 281→+			if err := json.Unmarshal(block.Input, &toolInput); err != nil {
 282→+				continue
 283→+			}
 284→+
 285→+			file := toolInput.FilePath
 286→+			if file == "" {
 287→+				file = toolInput.NotebookPath
 288→+			}
 289→+			if file != "" && !seen[file] {
 290→+				seen[file] = true
 291→+				files = append(files, file)
 292→+			}
 293→+		}
 294→+	}
 295→+
 296→+	return files
 297→+}
