 357→+// InstallHooks installs Cursor hooks in .cursor/hooks.json.
 358→+// If force is true, removes existing Entire hooks before installing.
 359→+// Returns the number of hooks installed.
 360→+// Unknown top-level fields and hook types are preserved on round-trip.
 361→+func (c *CursorAgent) InstallHooks(localDev bool, force bool) (int, error) {
 362→+	repoRoot, err := paths.RepoRoot()
 363→+	if err != nil {
 364→+		repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when RepoRoot() fails (tests run outside git repos)
 365→+		if err != nil {
 366→+			return 0, fmt.Errorf("failed to get current directory: %w", err)
 367→+		}
 368→+	}
 369→+
 370→+	hooksPath := filepath.Join(repoRoot, ".cursor", HooksFileName)
 371→+
 372→+	// Use raw maps to preserve unknown fields on round-trip
 373→+	var rawFile map[string]json.RawMessage
 374→+	var rawHooks map[string]json.RawMessage
 375→+
 376→+	existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
 377→+	if readErr == nil {
 378→+		if err := json.Unmarshal(existingData, &rawFile); err != nil {
 379→+			return 0, fmt.Errorf("failed to parse existing "+HooksFileName+": %w", err)
 380→+		}
 381→+		if hooksRaw, ok := rawFile["hooks"]; ok {
 382→+			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
 383→+				return 0, fmt.Errorf("failed to parse hooks in "+HooksFileName+": %w", err)
 384→+			}
 385→+		}
 386→+	} else {
 387→+		rawFile = map[string]json.RawMessage{
 388→+			"version": json.RawMessage(`1`),
 389→+		}
 390→+	}
 391→+
 392→+	if rawHooks == nil {
 393→+		rawHooks = make(map[string]json.RawMessage)
 394→+	}
 395→+
 396→+	// Parse only the hook types we manage
 397→+	var sessionStart, sessionEnd, beforeSubmitPrompt, stop, preToolUse, postToolUse []CursorHookEntry
 398→+	parseCursorHookType(rawHooks, "sessionStart", &sessionStart)
 399→+	parseCursorHookType(rawHooks, "sessionEnd", &sessionEnd)
 400→+	parseCursorHookType(rawHooks, "beforeSubmitPrompt", &beforeSubmitPrompt)
 401→+	parseCursorHookType(rawHooks, "stop", &stop)
 402→+	parseCursorHookType(rawHooks, "preToolUse", &preToolUse)
 403→+	parseCursorHookType(rawHooks, "postToolUse", &postToolUse)
 404→+
 405→+	// If force is true, remove all existing Entire hooks first
 406→+	if force {
 407→+		sessionStart = removeEntireHooks(sessionStart)
 408→+		sessionEnd = removeEntireHooks(sessionEnd)
 409→+		beforeSubmitPrompt = removeEntireHooks(beforeSubmitPrompt)
 410→+		stop = removeEntireHooks(stop)
 411→+		preToolUse = removeEntireHooks(preToolUse)
 412→+		postToolUse = removeEntireHooks(postToolUse)
 413→+	}
 414→+
 415→+	// Define hook commands
 416→+	var cmdPrefix string
 417→+	if localDev {
 418→+		cmdPrefix = "go run ${CURSOR_PROJECT_DIR}/cmd/entire/main.go hooks cursor "
 419→+	} else {
 420→+		cmdPrefix = "entire hooks cursor "
 421→+	}
 422→+
 423→+	sessionStartCmd := cmdPrefix + "session-start"
 424→+	sessionEndCmd := cmdPrefix + "session-end"
 425→+	beforeSubmitPromptCmd := cmdPrefix + "before-submit-prompt"
 426→+	stopCmd := cmdPrefix + "stop"
 427→+	preTaskCmd := cmdPrefix + "pre-task"
 428→+	postTaskCmd := cmdPrefix + "post-task"
 429→+	postTodoCmd := cmdPrefix + "post-todo"
 430→+
 431→+	count := 0
 432→+
 433→+	// Add hooks if they don't exist
 434→+	if !hookCommandExists(sessionStart, sessionStartCmd) {
 435→+		sessionStart = append(sessionStart, CursorHookEntry{Command: sessionStartCmd})
 436→+		count++
 437→+	}
 438→+	if !hookCommandExists(sessionEnd, sessionEndCmd) {
 439→+		sessionEnd = append(sessionEnd, CursorHookEntry{Command: sessionEndCmd})
 440→+		count++
 441→+	}
 442→+	if !hookCommandExists(beforeSubmitPrompt, beforeSubmitPromptCmd) {
 443→+		beforeSubmitPrompt = append(beforeSubmitPrompt, CursorHookEntry{Command: beforeSubmitPromptCmd})
 444→+		count++
 445→+	}
 446→+	if !hookCommandExists(stop, stopCmd) {
 447→+		stop = append(stop, CursorHookEntry{Command: stopCmd})
 448→+		count++
 449→+	}
 450→+	if !hookCommandExistsWithMatcher(preToolUse, "Task", preTaskCmd) {
 451→+		preToolUse = append(preToolUse, CursorHookEntry{Command: preTaskCmd, Matcher: "Task"})
 452→+		count++
 453→+	}
 454→+	if !hookCommandExistsWithMatcher(postToolUse, "Task", postTaskCmd) {
 455→+		postToolUse = append(postToolUse, CursorHookEntry{Command: postTaskCmd, Matcher: "Task"})
 456→+		count++
 457→+	}
 458→+	if !hookCommandExistsWithMatcher(postToolUse, "TodoWrite", postTodoCmd) {
 459→+		postToolUse = append(postToolUse, CursorHookEntry{Command: postTodoCmd, Matcher: "TodoWrite"})
 460→+		count++
 461→+	}
 462→+
 463→+	if count == 0 {
 464→+		return 0, nil
 465→+	}
 466→+
 467→+	// Marshal modified hook types back into rawHooks
 468→+	marshalCursorHookType(rawHooks, "sessionStart", sessionStart)
 469→+	marshalCursorHookType(rawHooks, "sessionEnd", sessionEnd)
 470→+	marshalCursorHookType(rawHooks, "beforeSubmitPrompt", beforeSubmitPrompt)
 471→+	marshalCursorHookType(rawHooks, "stop", stop)
 472→+	marshalCursorHookType(rawHooks, "preToolUse", preToolUse)
 473→+	marshalCursorHookType(rawHooks, "postToolUse", postToolUse)
 474→+
 475→+	// Marshal hooks and update raw file
 476→+	hooksJSON, err := json.Marshal(rawHooks)
 477→+	if err != nil {
 478→+		return 0, fmt.Errorf("failed to marshal hooks: %w", err)
 479→+	}
 480→+	rawFile["hooks"] = hooksJSON
 481→+
 482→+	// Write to file
 483→+	if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
 484→+		return 0, fmt.Errorf("failed to create .cursor directory: %w", err)
 485→+	}
 486→+
 487→+	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
 488→+	if err != nil {
 489→+		return 0, fmt.Errorf("failed to marshal "+HooksFileName+": %w", err)
 490→+	}
 491→+
 492→+	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
 493→+		return 0, fmt.Errorf("failed to write "+HooksFileName+": %w", err)
 494→+	}
 495→+
 496→+	return count, nil
 497→+}
