 529→+	parseCursorHookType(rawHooks, "sessionStart", &sessionStart)
 530→+	parseCursorHookType(rawHooks, "sessionEnd", &sessionEnd)
 531→+	parseCursorHookType(rawHooks, "beforeSubmitPrompt", &beforeSubmitPrompt)
 532→+	parseCursorHookType(rawHooks, "stop", &stop)
 533→+	parseCursorHookType(rawHooks, "preToolUse", &preToolUse)
 534→+	parseCursorHookType(rawHooks, "postToolUse", &postToolUse)
 535→+
