 546→+	marshalCursorHookType(rawHooks, "sessionEnd", sessionEnd)
 547→+	marshalCursorHookType(rawHooks, "beforeSubmitPrompt", beforeSubmitPrompt)
 548→+	marshalCursorHookType(rawHooks, "stop", stop)
 549→+	marshalCursorHookType(rawHooks, "preToolUse", preToolUse)
 550→+	marshalCursorHookType(rawHooks, "postToolUse", postToolUse)
 551→+
 552→+	// Marshal hooks back (preserving unknown hook types)
 553→+	if len(rawHooks) > 0 {
 554→+		hooksJSON, err := json.Marshal(rawHooks)
 555→+		if err != nil {
 556→+			return fmt.Errorf("failed to marshal hooks: %w", err)
 557→+		}
 558→+		rawFile["hooks"] = hooksJSON
 559→+	} else {
 560→+		delete(rawFile, "hooks")
 561→+	}
 562→+
 563→+	// Write back
 564→+	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
 565→+	if err != nil {
