 612→+// parseCursorHookType parses a specific hook type from rawHooks into the target slice.
 613→+// Silently ignores parse errors (leaves target unchanged).
 614→+func parseCursorHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]CursorHookEntry) {
 615→+	if data, ok := rawHooks[hookType]; ok {
