 621→+// marshalCursorHookType marshals a hook type back into rawHooks.
 622→+// If the slice is empty, removes the key from rawHooks.
 623→+func marshalCursorHookType(rawHooks map[string]json.RawMessage, hookType string, entries []CursorHookEntry) {
 624→+	if len(entries) == 0 {
 625→+		delete(rawHooks, hookType)
 626→+		return
 627→+	}
 628→+	data, err := json.Marshal(entries)
 629→+	if err != nil {
 630→+		return // Silently ignore marshal errors (shouldn't happen)
 631→+	}
 632→+	rawHooks[hookType] = data
 633→+}
