 655→+func isEntireHook(command string) bool {
 656→+	for _, prefix := range entireHookPrefixes {
 657→+		if strings.HasPrefix(command, prefix) {
 658→+			return true
 659→+		}
 660→+	}
 661→+	return false
 662→+}
 663→+
 664→+func hasEntireHook(entries []CursorHookEntry) bool {
 665→+	for _, entry := range entries {
 666→+		if isEntireHook(entry.Command) {
 667→+			return true
 668→+		}
 669→+	}
 670→+	return false
 671→+}
 672→+
 673→+func removeEntireHooks(entries []CursorHookEntry) []CursorHookEntry {
 674→+	result := make([]CursorHookEntry, 0, len(entries))
 675→+	for _, entry := range entries {
 676→+		if !isEntireHook(entry.Command) {
 677→+			result = append(result, entry)
 678→+		}
 679→+	}
 680→+	return result
 681→+}
