1152→+
1153→+// ParseHookEvent translates a Cursor hook into a normalized lifecycle Event.
1154→+// Returns nil if the hook has no lifecycle significance.
1155→+func (c *CursorAgent) ParseHookEvent(hookName string, stdin io.Reader) (*agent.Event, error) {
1156→+	switch hookName {
1157→+	case HookNameSessionStart:
1158→+		return c.parseSessionStart(stdin)
1159→+	case HookNameBeforeSubmitPrompt:
1160→+		return c.parseTurnStart(stdin)
1161→+	case HookNameStop:
1162→+		return c.parseTurnEnd(stdin)
1163→+	case HookNameSessionEnd:
1164→+		return c.parseSessionEnd(stdin)
1165→+	case HookNamePreTask:
1166→+		return c.parseSubagentStart(stdin)
1167→+	case HookNamePostTask:
1168→+		return c.parseSubagentEnd(stdin)
1169→+	case HookNamePostTodo:
1170→+		// PostTodo is handled outside the generic dispatcher (incremental checkpoints).
1171→+		return nil, nil //nolint:nilnil // nil event = no lifecycle action
1172→+	default:
1173→+		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
1174→+	}
1175→+}
