166→// ReadSession reads a session from Cursor's storage (JSONL transcript file).
167→func (c *CursorAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
168→	if input.SessionRef == "" {
169→		return nil, errors.New("session reference (transcript path) is required")
170→	}
171→
172→	data, err := os.ReadFile(input.SessionRef)
173→	if err != nil {
174→		return nil, fmt.Errorf("failed to read transcript: %w", err)
175→	}
176→
177→	lines, err := transcript.ParseFromBytes(data)
178→	if err != nil {
179→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
180→	}
181→
182→	return &agent.AgentSession{
183→		SessionID:     input.SessionID,
184→		AgentName:     c.Name(),
185→		SessionRef:    input.SessionRef,
186→		StartTime:     time.Now(),
187→		NativeData:    data,
188→		ModifiedFiles: extractModifiedFiles(lines),
189→	}, nil
190→}
