197→
198→	if session.AgentName != "" && session.AgentName != c.Name() {
199→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
200→	}
201→
202→	if session.SessionRef == "" {
203→		return errors.New("session reference (transcript path) is required")
204→	}
205→
206→	if len(session.NativeData) == 0 {
207→		return errors.New("session has no native data to write")
208→	}
209→
210→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
211→		return fmt.Errorf("failed to write transcript: %w", err)
212→	}
213→
214→	return nil
215→}
