			if !isModifyTool {
				continue
			}

			var toolInput transcript.ToolInput
			if err := json.Unmarshal(block.Input, &toolInput); err != nil {
				continue
			}

			file := toolInput.FilePath
			if file == "" {
				file = toolInput.NotebookPath
			}
			if file != "" && !seen[file] {
				seen[file] = true
				files = append(files, file)
			}
		}
	}

	return files
}

